/// A callisto subcommand.
#[derive(Subcommand, Clone, Debug)]
pub enum Command {
    /// Create a new changeset describing pending package changes.
    Add(AddArgs),
    /// Show the workspace's pending changesets and diagnostics.
    Status(StatusArgs),
    /// Print the workspace's native-build target matrix as JSON or a table.
    #[command(hide = true)]
    Matrix(MatrixArgs),
    /// Consume pending changesets and bump package versions accordingly.
    Version(VersionArgs),
    /// Manage prerelease mode for the workspace.
    #[command(subcommand)]
    Pre(PreArgs),
    /// Apply a temporary, non-persistent version bump for a snapshot release.
    Snapshot(SnapshotArgs),
    /// Scaffold Callisto configuration in the current workspace.
    Init(InitArgs),
    /// Generate a pull request body summarizing pending release changes.
    #[command(hide = true)]
    ComposePrBody(ComposePrBodyArgs),
    /// Publish every package whose current version has not been released yet.
    Release(ReleaseCommandArgs),
    /// Decide the next managed release-pull-request operation from a forge snapshot.
    #[command(subcommand, hide = true)]
    ReleasePr(ReleasePrArgs),
    /// Generate shell completion scripts.
    Completions(CompletionsArgs),
    /// Print the JSON schema for a report type.
    #[command(hide = true)]
    Schema(SchemaArgs),
    /// Print a subcommand's help text.
    #[command(hide = true)]
    Help(HelpArgs),
}

impl Command {
    /// This subcommand's name exactly as clap parses it, for the JSON error
    /// envelope's `"command"` field -- computed from the parsed subcommand
    /// rather than duplicated as a literal at each error call site.
    pub fn name(&self) -> &'static str {
        match self {
            Command::Add(_) => "add",
            Command::Status(_) => "status",
            Command::Matrix(_) => "matrix",
            Command::Version(_) => "version",
            Command::Pre(_) => "pre",
            Command::Snapshot(_) => "snapshot",
            Command::Init(_) => "init",
            Command::ComposePrBody(_) => "compose-pr-body",
            Command::Release(_) => "release",
            Command::ReleasePr(_) => "release-pr",
            Command::Completions(_) => "completions",
            Command::Schema(_) => "schema",
            Command::Help(_) => "help",
        }
    }
}

/// Arguments for the `schema` command.
#[derive(Args, Clone, Debug, Default)]
pub struct SchemaArgs {
    /// Report type to print the schema for; defaults to status.
    #[arg(long = "type", value_enum)]
    pub target_type: Option<SchemaReportType>,
}

/// The one registry of report/document types `schema --type` can print --
/// the sole source `SchemaArgs.target_type` and `callisto-cli::commands::schema`
/// both parse and match against, so a new report type is added in one place.
#[derive(ValueEnum, Clone, Copy, Debug, PartialEq, Eq, Default)]
pub enum SchemaReportType {
    #[default]
    Status,
    Version,
    Snapshot,
    Init,
    Changeset,
    /// The on-disk `.changeset/pre.json` file shape -- not `callisto pre`'s
    /// own `--format json` report, which `PreReport` describes instead.
    #[value(name = "pre-state")]
    PreState,
    Matrix,
    ReleaseReceipt,
}

